int64_t he_is_multiply_prime(int64_t a) {
  int64_t count = 0;
  int64_t p;
  if (a <= 1) return 0;
  /* Same predicate as searching primes <= 100 whose product is a:
     exactly three prime factors, counting multiplicity, each <= 100. */
  while ((a % 2) == 0) {
    count++;
    a /= 2;
    if (count > 3) return 0;
  }
  for (p = 3; p <= a && p <= 100; p += 2) {
    while ((a % p) == 0) {
      count++;
      a /= p;
      if (count > 3) return 0;
    }
  }
  if (a != 1) return 0;
  return count == 3 ? 1 : 0;
}

int64_t he_is_simple_power(int64_t x, int64_t n) {
