    last = x % 10;
    first = x;
    while (first >= 10) first /= 10;
    if ((first % 2) == 1 && (last % 2) == 1) count++;
  }
  return count;
}

int64_t he_x_or_y(int64_t n, int64_t x, int64_t y) {
  int64_t i;
  if (n <= 1) return y;
  for (i = 2; i * i <= n; i++) {
    if ((n % i) == 0) return y;
  }
  return x;
}

int64_t he_double_the_difference(const int64_t *lst, int64_t n) {
  int64_t s = 0, i, v;
  for (i = 0; i < n; i++) {
    v = lst[i];
    if (v > 0 && (v % 2) != 0) s += v * v;
  }
  return s;
}

void he_compare_scores(const int64_t *game, const int64_t *guess, int64_t n, int64_t *out) {
  int64_t i, d;
  for (i = 0; i < n; i++) {
    d = game[i] - guess[i];
    if (d < 0) d = -d;
    out[i] = d;
  }
}

int64_t he_even_odd_count(int64_t num, int64_t *odd_count) {
  int64_t even_count = 0;
  int64_t odd = 0;
  int64_t d;
  if (num < 0) num = -num;
  if (num == 0) {
    *odd_count = 0;
    return 1;
  }
  while (num > 0) {
    d = num % 10;
    if ((d % 2) == 0) even_count++;
    else odd++;
    num /= 10;
  }
  *odd_count = odd;
  return even_count;
}

int64_t he_right_angle_triangle(int64_t a, int64_t b, int64_t c) {
  if (a * a == b * b + c * c) return 1;
  if (b * b == a * a + c * c) return 1;
  if (c * c == a * a + b * b) return 1;
  return 0;
}

int64_t he_eat(int64_t number, int64_t need, int64_t remaining, int64_t *left) {
  if (need <= remaining) {
    *left = remaining - need;
    return number + need;
  }
  *left = 0;
  return number + remaining;
}

int64_t he_generate_integers(int64_t a, int64_t b, int64_t *out) {
  int64_t lower = a < b ? a : b;
  int64_t upper = a > b ? a : b;
  int64_t i, m = 0;
  if (lower < 2) lower = 2;
  if (upper > 8) upper = 8;
  for (i = lower; i <= upper; i++) {
    if ((i % 2) == 0) out[m++] = i;
  }
  return m;
}
